#include <stdio.h>

int main(void)
{
    int age = 30;
    int *p = &age;                 /* p holds the address of age */

    printf("age = %d\n", age);
    printf("*p  = %d\n", *p);      /* read through the pointer */

    *p = 31;                       /* write through the pointer */
    printf("age = %d\n", age);

    printf("same address: %d\n", p == &age);
    printf("sizeof p = %zu bytes\n", sizeof p);
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b)
{
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

void min_max(const int *values, size_t n, int *min, int *max)
{
    *min = *max = values[0];
    for (size_t i = 1; i < n; i++) {
        if (values[i] < *min) *min = values[i];
        if (values[i] > *max) *max = values[i];
    }
}

int main(void)
{
    int x = 1, y = 2;
    swap(&x, &y);
    printf("x = %d, y = %d\n", x, y);

    int data[] = {7, -3, 12, 5};
    int lo, hi;
    min_max(data, 4, &lo, &hi);
    printf("min = %d, max = %d\n", lo, hi);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int data[] = {10, 20, 30, 40};
    int *p = data;                /* same as &data[0] */

    printf("%d %d\n", *p, p[2]);
    printf("%d\n", *(p + 3));

    p++;                          /* now points at data[1] */
    printf("%d\n", *p);

    for (int *q = data; q < data + 4; q++) {
        printf("q -> %d\n", *q);
    }
    printf("sizeof data = %zu, sizeof p = %zu\n", sizeof data, sizeof p);
    return 0;
}

#include <stdio.h>

size_t count_positive(const int *values, size_t n)
{
    size_t count = 0;
    for (size_t i = 0; i < n; i++) {
        if (values[i] > 0) count++;
    }
    return count;
}

int main(void)
{
    int *maybe = NULL;
    if (maybe == NULL) {
        printf("maybe points nowhere yet\n");
